import java.util.Scanner;

public class Main {
    static final int MAXN = 1100000;
    static final long MOD = 1000000007;
    static boolean[] vis = new boolean[MAXN];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long K = sc.nextLong();

        if (K == 0) {
            System.out.println(fastPow(p, p - 1));
            return;
        } else if (K == 1) {
            System.out.println(fastPow(p, p));
            return;
        }

        int cnt = 0;
        for (int i = 0; i < p; i++) {
            if (vis[i]) continue;
            int size = 0;
            long tmp = i;
            while (!vis[(int) tmp]) {
                size++;
                vis[(int) tmp] = true;
                tmp = (tmp * K) % p;
            }
            if (size > 1) cnt++;
        }
        System.out.println(fastPow(p, cnt));
    }

    static long fastPow(long base, long pow) {
        long ans = 1;
        while (pow > 0) {
            if ((pow & 1) == 1) {
                ans = (ans * base) % MOD;
            }
            base = (base * base) % MOD;
            pow >>= 1;
        }
        return ans;
    }
}
